  "CREATE TABLE IF NOT EXISTS p_tenants (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, niche TEXT NOT NULL, status TEXT NOT NULL, created INTEGER NOT NULL, email TEXT, stripe_customer TEXT, stripe_sub TEXT, sub_status TEXT, sub_checked INTEGER, brand TEXT, prefs TEXT, note TEXT)",
  "CREATE TABLE IF NOT EXISTS p_users (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, email TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, hash TEXT NOT NULL, iter INTEGER NOT NULL, created INTEGER NOT NULL, name TEXT)",
  "CREATE TABLE IF NOT EXISTS p_sessions (h TEXT PRIMARY KEY, uid TEXT NOT NULL, kind TEXT NOT NULL, created INTEGER NOT NULL, expires INTEGER NOT NULL)",
  "CREATE TABLE IF NOT EXISTS p_attempts (k TEXT NOT NULL, ts INTEGER NOT NULL)",
  "CREATE INDEX IF NOT EXISTS p_attempts_k ON p_attempts (k, ts)",
  "CREATE TABLE IF NOT EXISTS p_admins (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, hash TEXT NOT NULL, iter INTEGER NOT NULL, created INTEGER NOT NULL, last_login INTEGER, disabled INTEGER NOT NULL DEFAULT 0, invited_by TEXT)",   // 29 oct 2026: admins of 404 Content only
  "CREATE TABLE IF NOT EXISTS p_tokens (h TEXT PRIMARY KEY, kind TEXT NOT NULL, tenant_id TEXT, email TEXT, data TEXT, expires INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0)",
  "CREATE TABLE IF NOT EXISTS p_signups (id TEXT PRIMARY KEY, email TEXT NOT NULL, name TEXT NOT NULL, niche TEXT NOT NULL, phone TEXT, checkout TEXT, created INTEGER NOT NULL, status TEXT NOT NULL, tenant_id TEXT)",
  "CREATE TABLE IF NOT EXISTS p_train (tenant_id TEXT PRIMARY KEY, data TEXT NOT NULL, updated INTEGER NOT NULL)",
  "CREATE TABLE IF NOT EXISTS p_conn (tenant_id TEXT NOT NULL, kind TEXT NOT NULL, ext TEXT NOT NULL, token TEXT NOT NULL, data TEXT, created INTEGER NOT NULL, expires INTEGER, PRIMARY KEY (tenant_id, kind))",
  "CREATE INDEX IF NOT EXISTS p_conn_ext ON p_conn (kind, ext)",
  "CREATE TABLE IF NOT EXISTS p_leads (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, name TEXT, phone TEXT, ig TEXT, email TEXT, channel TEXT NOT NULL, source TEXT, stage TEXT NOT NULL, notes TEXT, data TEXT, created INTEGER NOT NULL, last_in INTEGER, last_out INTEGER, followups INTEGER NOT NULL DEFAULT 0, bot INTEGER NOT NULL DEFAULT 1, value INTEGER NOT NULL DEFAULT 0, unread INTEGER NOT NULL DEFAULT 0, handoff INTEGER NOT NULL DEFAULT 0)",
  "CREATE INDEX IF NOT EXISTS p_leads_t ON p_leads (tenant_id, last_in)",
  "CREATE INDEX IF NOT EXISTS p_leads_phone ON p_leads (tenant_id, phone)",
