  "CREATE INDEX IF NOT EXISTS p_msgs_l ON p_msgs (lead_id, ts)",
  "CREATE INDEX IF NOT EXISTS p_msgs_ext ON p_msgs (tenant_id, ext)",
  "CREATE TABLE IF NOT EXISTS p_appts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, lead_id TEXT, name TEXT, phone TEXT, start INTEGER NOT NULL, mins INTEGER NOT NULL, service TEXT, status TEXT NOT NULL, created INTEGER NOT NULL, reminded INTEGER NOT NULL DEFAULT 0, via TEXT)",
  "CREATE INDEX IF NOT EXISTS p_appts_t ON p_appts (tenant_id, start)",
  "CREATE TABLE IF NOT EXISTS p_ideas (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, week TEXT NOT NULL, ord INTEGER NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL, created INTEGER NOT NULL, score INTEGER NOT NULL DEFAULT 0)",
  "CREATE INDEX IF NOT EXISTS p_ideas_t ON p_ideas (tenant_id, week)",
  "CREATE TABLE IF NOT EXISTS p_site (tenant_id TEXT PRIMARY KEY, data TEXT NOT NULL, status TEXT NOT NULL, updated INTEGER NOT NULL, published INTEGER, review_note TEXT, live TEXT)",
  "CREATE TABLE IF NOT EXISTS p_media (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, kind TEXT NOT NULL, mime TEXT NOT NULL, data TEXT NOT NULL, created INTEGER NOT NULL)",
  "CREATE INDEX IF NOT EXISTS p_media_t ON p_media (tenant_id, kind)",
  "CREATE TABLE IF NOT EXISTS p_events (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, kind TEXT NOT NULL, tenant_id TEXT, text TEXT NOT NULL, sent INTEGER NOT NULL DEFAULT 0)",
  "CREATE TABLE IF NOT EXISTS p_usage (tenant_id TEXT NOT NULL, day TEXT NOT NULL, ai_in INTEGER NOT NULL DEFAULT 0, ai_out INTEGER NOT NULL DEFAULT 0, msgs INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (tenant_id, day))",
  "CREATE TABLE IF NOT EXISTS p_push (ep TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, uid TEXT NOT NULL, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created INTEGER NOT NULL)",
