const getPath = (o, k) => k.split(".").reduce((a, p) => (a && typeof a === "object" ? a[p] : undefined), o);
function setPath(o, k, v) { const ps = k.split("."); let a = o; for (let i = 0; i < ps.length - 1; i++) { if (!a[ps[i]] || typeof a[ps[i]] !== "object") a[ps[i]] = {}; a = a[ps[i]]; } a[ps[ps.length - 1]] = v; }
// what the panel sends back is rebuilt field by field from the schema (nothing else is stored)
// only the fields of the schema are taken from what the panel sends; what the other plan's form holds is kept as it was
function cleanTrain(niche, inData, prev, plan) {
  const out = Object.assign(trainDefaults(niche, ""), JSON.parse(JSON.stringify(prev || {}))), sch = schemaFor(plan, niche);
  for (const k of ["negocio", "extra", "politicas", "legal", "asistente", "contenido"]) if (!out[k] || typeof out[k] !== "object") out[k] = {};
  out.agenda = prev && prev.agenda ? prev.agenda : out.agenda;
  for (const sec of sch) for (const f of sec.f) {
    const v = getPath(inData, f.k);
    if (f.type === "services") out.servicios = (Array.isArray(v) ? v : []).slice(0, 40).map((s) => ({ nombre: str(s && s.nombre, 80), precio: str(s && s.precio, 60), dur: clamp(s && s.dur, 5, 480, 30), nota: str(s && s.nota, 300) })).filter((s) => s.nombre);
    else if (f.type === "faq") out.faq = (Array.isArray(v) ? v : []).slice(0, 40).map((q) => ({ p: str(q && q.p, 200), r: str(q && q.r, 800) })).filter((q) => q.p && q.r);
    else if (f.type === "select") setPath(out, f.k, Object.keys(f.opts).includes(String(v)) ? String(v) : (f.def || Object.keys(f.opts)[0]));
    else setPath(out, f.k, str(v, f.type === "area" ? 1500 : 200));
  }
  if (plan !== "content") out.asistente.activo = getPath(inData, "asistente.activo") !== false;
  return out;
}
function cleanAgenda(a) {
  const hhmm = (s) => (typeof s === "string" && /^([01]\d|2[0-3]):[0-5]\d$/.test(s) ? s : null);
  const horario = [];
  for (let d = 0; d < 7; d++) {
    const day = Array.isArray(a && a.horario && a.horario[d]) ? a.horario[d] : [];
    horario.push(day.slice(0, 4).map((r) => [hhmm(r && r[0]), hhmm(r && r[1])]).filter((r) => r[0] && r[1] && r[0] < r[1]));
  }
  return { horario, dur: clamp(a && a.dur, 5, 480, 30), paso: [10, 15, 20, 30, 45, 60].includes(Number(a && a.paso)) ? Number(a.paso) : 30, cap: clamp(a && a.cap, 1, 20, 1),
    antelacion: clamp(a && a.antelacion, 0, 168, 2), horizonte: clamp(a && a.horizonte, 1, 90, 21),
    cerrado: (Array.isArray(a && a.cerrado) ? a.cerrado : []).filter((d) => typeof d === "string" && /^\d{4}-\d{2}-\d{2}$/.test(d)).slice(0, 100) };
}
function trainProgress(niche, d, plan) {
  let n = 0, ok = 0;
  for (const sec of schemaFor(plan, niche)) for (const f of sec.f) if (f.req) { n++; const v = f.type === "services" ? d.servicios : getPath(d, f.k); if (Array.isArray(v) ? v.length : v) ok++; }
  return Math.round((ok / n) * 100);
}
// the business, written out for the assistant with the same labels the client saw
function trainText(niche, d, plan) {
  const lines = [], n = NICHE[niche] || NICHE.general;
  lines.push("Tipo de negocio: " + n.label);
  for (const sec of schemaFor(plan, niche)) {
    if (sec.t.startsWith("Datos legales") || sec.t.startsWith("Cómo habla")) continue;
    const part = [];
    for (const f of sec.f) {
      if (f.type === "services") { for (const s of d.servicios || []) part.push("- " + s.nombre + (s.precio ? ": " + s.precio : "") + (s.dur ? " (" + s.dur + " min)" : "") + (s.nota ? ". " + s.nota : "")); }
      else if (f.type === "faq") { for (const q of d.faq || []) part.push("P: " + q.p + "\nR: " + q.r); }
      else if (f.type === "select") { const v = getPath(d, f.k); if (v && f.opts[v]) part.push(f.l + ": " + f.opts[v]); }
      else { const v = getPath(d, f.k); if (v) part.push(f.l + ": " + v); }
    }
    if (part.length) lines.push("## " + sec.t + "\n" + part.join("\n"));
  }
  // 27 oct 2026: what the owner told the AI in the interview (17-entrevista.js), in short sentences
  const sab = (Array.isArray(d.saber) ? d.saber : []).map((x) => x && x.t).filter(Boolean);
  if (sab.length) lines.push("## Lo que nos ha contado el dueño en la entrevista\n" + sab.slice(-120).map((x) => "- " + x).join("\n"));
  return lines.join("\n\n");
}
async function getTrain(env, tenantId) { const r = await env.DB.prepare("SELECT data FROM p_train WHERE tenant_id = ?1").bind(tenantId).first(); return r ? jparse(r.data, {}) : {}; }
const putTrain = (env, tenantId, d) => env.DB.prepare("INSERT INTO p_train (tenant_id, data, updated) VALUES (?1, ?2, ?3) ON CONFLICT(tenant_id) DO UPDATE SET data = excluded.data, updated = excluded.updated").bind(tenantId, JSON.stringify(d), Date.now()).run();

/* ---------- the agenda: free slots from the weekly hours, the length of each service, how many people can be seen at once and the
   appointments already made. The assistant, the web's booking form and the panel all book through here. ---------- */
function svcDur(train, service) {
  const ag = train.agenda || {}, s = (train.servicios || []).find((x) => x.nombre && service && x.nombre.toLowerCase() === String(service).toLowerCase());
  return s && s.dur ? s.dur : ag.dur || 30;
}
async function freeSlots(env, tenantId, train, day, service, now) {
  const ag = cleanAgenda(train.agenda || {}), dur = svcDur(train, service);
  now = now || Date.now();
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(day || ""); if (!m) return [];
  const y = +m[1], mo = +m[2], d = +m[3];
  const noon = Date.UTC(y, mo - 1, d, 12), wd = tzParts(noon).wd;
  if (ag.cerrado.includes(day)) return [];
  if (noon > now + (ag.horizonte + 1) * DAY) return [];
  const from = localMs(y, mo, d, 0, 0), to = from + 30 * 3600000;
  const appts = (await env.DB.prepare("SELECT start, mins FROM p_appts WHERE tenant_id = ?1 AND status = 'ok' AND start < ?3 AND start + mins * 60000 > ?2").bind(tenantId, from, to).all()).results || [];
  const out = [], earliest = now + ag.antelacion * 3600000;
  for (const r of ag.horario[wd] || []) {
    const [h1, m1] = r[0].split(":").map(Number), [h2, m2] = r[1].split(":").map(Number);
    const end = localMs(y, mo, d, h2, m2);
    for (let t = localMs(y, mo, d, h1, m1); t + dur * 60000 <= end; t += ag.paso * 60000) {
      if (t < earliest) continue;
      const busy = appts.filter((a) => a.start < t + dur * 60000 && a.start + a.mins * 60000 > t).length;
      if (busy < ag.cap) out.push(t);
    }
  }
  return out;
}
// the next days with room, for the assistant when the person has not said a day
async function nextSlots(env, tenantId, train, service, days, perDay) {
  const out = [], now = Date.now();
  for (let i = 0; i < (days || 7) && out.length < 12; i++) {
    const s = await freeSlots(env, tenantId, train, dayKey(now + i * DAY), service, now);
    if (s.length) out.push({ dia: dayKey(now + i * DAY), huecos: s.slice(0, perDay || 6) });
  }
  return out;
}
async function book(env, tenant, train, o) {
  const start = Number(o.start);
  if (!Number.isFinite(start)) return { error: "fecha" };
  const day = dayKey(start), slots = await freeSlots(env, tenant.id, train, day, o.service, Date.now());
  if (!slots.includes(start)) return { error: "ocupado" };
  const id = rid("pa_"), mins = svcDur(train, o.service);
  await env.DB.prepare("INSERT INTO p_appts (id, tenant_id, lead_id, name, phone, start, mins, service, status, created, via) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, 'ok', ?9, ?10)")
    .bind(id, tenant.id, o.leadId || null, str(o.name, 80) || null, o.phone || null, start, mins, str(o.service, 80) || null, Date.now(), o.via || "panel").run();
  // two bookings racing for the last place: the later one is undone
  const ag = cleanAgenda(train.agenda || {});
  const n = await env.DB.prepare("SELECT COUNT(*) AS n FROM p_appts WHERE tenant_id = ?1 AND status = 'ok' AND start < ?3 AND start + mins * 60000 > ?2").bind(tenant.id, start, start + mins * 60000).first();
  if (n.n > ag.cap) { await env.DB.prepare("DELETE FROM p_appts WHERE id = ?1").bind(id).run(); return { error: "ocupado" }; }
  if (o.leadId) await env.DB.prepare("UPDATE p_leads SET stage = 'cita' WHERE id = ?1 AND tenant_id = ?2 AND stage IN ('nuevo', 'conversando')").bind(o.leadId, tenant.id).run();
  await evt(env, "t_cita", tenant.id, "Nueva cita: " + (o.name || "sin nombre") + " · " + (o.service || "cita") + " · " + human(start) + (o.via === "bot" ? " (la ha cerrado tu asistente)" : o.via === "web" ? " (desde tu web)" : ""));
  return { ok: true, id, start, mins, cuando: human(start) };
}

/* ---------- the assistant: Claude with the business's training, four tools (free slots, book, save a detail, hand over to a person),
   the conversation so far, and the rules: it says it is a virtual assistant at the start (AI Act art. 50), it only talks about the business,
   it never invents prices or dates, and it hands over when it should. ---------- */
async function claude(env, tenantId, req) {
  const key = await cfg(env, "anthropic_key");
  if (!key) return { error: "ai_off" };
  let r, j;
  try {
    r = await fetch("https://api.anthropic.com/v1/messages", { method: "POST", headers: { "x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json" }, body: JSON.stringify(req) });
    j = await r.json();
  } catch (e) { return { error: "ai_net" }; }
  if (!r.ok) return { error: "ai_" + r.status, detail: j && j.error && j.error.message };
  if (tenantId && j.usage) await usage(env, tenantId, (j.usage.input_tokens || 0) + (j.usage.cache_read_input_tokens || 0) + (j.usage.cache_creation_input_tokens || 0), j.usage.output_tokens || 0, 0);
  return j;
}
