async function apiLeadEdit(req, env, me, id) {
  const l = await leadOf(env, me, id); if (!l) return bad("lead", 404);
  const b = await body(req, 20000); if (!b) return bad("body");
  const t = await tenantOf(env, me.tenant_id), stages = prefsOf(t).stages.map((s) => s.k);
  const set = [], args = [];
  const put = (col, v) => { set.push(col + " = ?" + (args.length + 1)); args.push(v); };
  if ("stage" in b) { if (!stages.includes(b.stage)) return bad("stage"); put("stage", b.stage); }
  if ("name" in b) put("name", str(b.name, 80) || null);
  if ("phone" in b) { const p = normPhone(str(b.phone, 30)); if (p && !okPhone(p)) return bad("phone"); put("phone", p || null); }
  if ("email" in b) { const e = str(b.email, 160).toLowerCase(); if (e && !okEmail(e)) return bad("email"); put("email", e || null); }
  if ("notes" in b) put("notes", str(b.notes, 4000) || null);
  if ("value" in b) put("value", clamp(b.value, 0, 10000000, 0));
  if ("bot" in b) { put("bot", b.bot ? 1 : 0); if (b.bot) put("handoff", 0); }
  if ("data" in b && b.data && typeof b.data === "object") { const d = {}; for (const k of Object.keys(b.data).slice(0, 30)) d[str(k, 40)] = str(String(b.data[k] == null ? "" : b.data[k]), 500); put("data", JSON.stringify(d)); }
  if (!set.length) return json({ ok: true });
  args.push(id, me.tenant_id);
  await env.DB.prepare("UPDATE p_leads SET " + set.join(", ") + " WHERE id = ?" + (args.length - 1) + " AND tenant_id = ?" + args.length).bind(...args).run();
  return json({ ok: true });
}
