async function putMedia(env, tenantId, kind, dataUrl, max) {
  const m = /^data:(image\/(?:png|jpeg|webp|svg\+xml));base64,([A-Za-z0-9+/=]+)$/.exec(String(dataUrl || ""));
  if (!m) return { error: "image" };
  if (m[1] === "image/svg+xml") return { error: "image" };   // no SVG: it could carry script
  if (m[2].length > max) return { error: "big" };
  const id = rid("md_");
  await env.DB.prepare("INSERT INTO p_media (id, tenant_id, kind, mime, data, created) VALUES (?1, ?2, ?3, ?4, ?5, ?6)").bind(id, tenantId, kind, m[1], m[2], Date.now()).run();
  return { id };
}
async function media(env, id) {
  if (!/^md_[A-Za-z0-9_-]{12}$/.test(id)) return new Response("", { status: 404 });
  const r = await env.DB.prepare("SELECT mime, data FROM p_media WHERE id = ?1").bind(id).first();
  if (!r) return new Response("", { status: 404 });
  return new Response(unb64(r.data), { headers: { "content-type": r.mime, "cache-control": "public, max-age=31536000, immutable", "x-content-type-options": "nosniff" } });
}
