  if (!/^https?:$/.test(x.protocol) || x.username || x.password || (x.port && !["80", "443"].includes(x.port))) return null;
  const h = x.hostname.toLowerCase();
  if (!h.includes(".") || /^[\d.]+$/.test(h) || h.includes(":") || h.startsWith("[") || /(^|\.)(localhost|local|internal|lan|home|corp|test|invalid|example|arpa)$/.test(h)) return null;
  x.hash = "";
