    if (r.body && r.body.getReader) {
      const reader = r.body.getReader();
      while (n < max) { const x = await reader.read(); if (x.done) break; parts.push(x.value); n += x.value.length; }
      try { reader.cancel(); } catch (e) { /* done */ }
    } else { const u8 = new Uint8Array(await r.arrayBuffer()); parts.push(u8); n = u8.length; }
    const all = new Uint8Array(Math.min(n, max)); let o = 0;
    for (const p of parts) { const take = Math.min(p.length, all.length - o); all.set(p.subarray(0, take), o); o += take; if (o >= all.length) break; }
    let cs = /charset=([\w-]+)/.exec(ct); cs = cs ? cs[1] : "";
