/* ---------- notices on the client's phone (Web Push, RFC 8291 + VAPID): «hoy toca grabar», a new calendar, a new appointment… ---------- */
const VAPID_SUB = "mailto:hola@404growth.com";
const cat = (...a) => { const n = a.reduce((s, x) => s + x.length, 0), o = new Uint8Array(n); let i = 0; for (const x of a) { o.set(x, i); i += x.length; } return o; };
async function hkdf(salt, ikm, info, len) {
  const k = await crypto.subtle.importKey("raw", ikm, "HKDF", false, ["deriveBits"]);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: "HKDF", hash: "SHA-256", salt, info }, k, len * 8));
}
async function vapidKeys(env) {
  const raw = await cfg(env, "vapid"), j = raw ? jparse(raw, null) : null;
  if (j && j.pub && j.jwk) return j;
  const kp = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"]);
  const k = { pub: b64(new Uint8Array(await crypto.subtle.exportKey("raw", kp.publicKey))), jwk: await crypto.subtle.exportKey("jwk", kp.privateKey) };
  await cfgSet(env, "vapid", JSON.stringify(k));
  return k;
}
async function vapidAuth(env, endpoint) {
  const K = await vapidKeys(env), aud = new URL(endpoint).origin;
  const h = b64(enc.encode(JSON.stringify({ typ: "JWT", alg: "ES256" })));
  const c = b64(enc.encode(JSON.stringify({ aud, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub: VAPID_SUB })));
  const key = await crypto.subtle.importKey("jwk", K.jwk, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
  const sig = new Uint8Array(await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, enc.encode(h + "." + c)));
  return "vapid t=" + h + "." + c + "." + b64(sig) + ", k=" + K.pub;
}
async function pushBody(p256dh, auth, text) {
  const ua = unb64(p256dh), sec = unb64(auth);
  const as = await crypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, true, ["deriveBits"]);
  const asPub = new Uint8Array(await crypto.subtle.exportKey("raw", as.publicKey));
  const uaKey = await crypto.subtle.importKey("raw", ua, { name: "ECDH", namedCurve: "P-256" }, false, []);
  const shared = new Uint8Array(await crypto.subtle.deriveBits({ name: "ECDH", public: uaKey }, as.privateKey, 256));
  const ikm = await hkdf(sec, shared, cat(enc.encode("WebPush: info\0"), ua, asPub), 32);
  const salt = rand(16);
  const cek = await hkdf(salt, ikm, enc.encode("Content-Encoding: aes128gcm\0"), 16);
  const nonce = await hkdf(salt, ikm, enc.encode("Content-Encoding: nonce\0"), 12);
  const k = await crypto.subtle.importKey("raw", cek, "AES-GCM", false, ["encrypt"]);
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv: nonce }, k, cat(enc.encode(text), new Uint8Array([2]))));
  return cat(salt, new Uint8Array([0, 0, 16, 0]), new Uint8Array([asPub.length]), asPub, ct);
}
// the push services of Chrome, Firefox, Edge and Safari (a subscription can only point there)
const PUSH_HOST = /^https:\/\/(fcm\.googleapis\.com|updates\.push\.services\.mozilla\.com|[a-z0-9-]+\.notify\.windows\.com|web\.push\.apple\.com|[a-z0-9.-]+\.push\.apple\.com)\//;
async function pushTenant(env, tenantId, msg, uid) {
  /* 27 oct 2026: the phones belong to the account (its main business). A notice about a 2nd or 3rd business goes to the same phones, says
     which business it is about and opens the panel on that business (?b=) */
  const bt = await env.DB.prepare("SELECT id, name, parent FROM p_tenants WHERE id = ?1").bind(tenantId).first();
  if (bt && bt.parent) { msg = Object.assign({}, msg, { title: String(msg.title || "") + " · " + bt.name, url: String(msg.url || "/app").replace(/^\/app/, "/app?b=" + bt.id) }); tenantId = bt.parent; }
  else if (bt && msg.url && (await env.DB.prepare("SELECT 1 FROM p_tenants WHERE parent = ?1 AND status != 'closed'").bind(bt.id).first())) msg = Object.assign({}, msg, { title: String(msg.title || "") + " · " + bt.name, url: String(msg.url).replace(/^\/app/, "/app?b=" + bt.id) });
  const subs = (await env.DB.prepare("SELECT ep, p256dh, auth FROM p_push WHERE tenant_id = ?1" + (uid ? " AND uid = ?2" : "")).bind(...(uid ? [tenantId, uid] : [tenantId])).all()).results || [];
  const text = JSON.stringify(msg).slice(0, 3000), out = [];
  for (const s of subs) {
    let st = 0;
    try {
      const r = await fetch(s.ep, { method: "POST", headers: { "content-type": "application/octet-stream", "content-encoding": "aes128gcm", ttl: "86400", urgency: "normal", authorization: await vapidAuth(env, s.ep) }, body: await pushBody(s.p256dh, s.auth, text) });
      st = r.status;
    } catch (e) { st = -1; }
    out.push(st);
    if (st === 404 || st === 410) await env.DB.prepare("DELETE FROM p_push WHERE ep = ?1").bind(s.ep).run();
  }
  return out;
}
async function apiPush(req, env, me, p) {
  if (p === "key") return json({ key: (await vapidKeys(env)).pub });
  const b = (await body(req, 5000)) || {};
  if (p === "sub") {
    const k = b.keys || {};
    if (typeof b.endpoint !== "string" || b.endpoint.length > 900 || !PUSH_HOST.test(b.endpoint) || !/^[A-Za-z0-9_-]{80,100}$/.test(k.p256dh || "") || !/^[A-Za-z0-9_-]{16,30}$/.test(k.auth || "")) return bad("body");
    const home = me.home || me.tenant_id;   // 27 oct 2026: the phones are the account's, whichever business is open
    const n = await env.DB.prepare("SELECT COUNT(*) AS n FROM p_push WHERE tenant_id = ?1").bind(home).first();
    if (n.n >= 10) await env.DB.prepare("DELETE FROM p_push WHERE ep IN (SELECT ep FROM p_push WHERE tenant_id = ?1 ORDER BY created LIMIT 1)").bind(home).run();
    await env.DB.prepare("INSERT INTO p_push (ep, tenant_id, uid, p256dh, auth, created) VALUES (?1, ?2, ?3, ?4, ?5, ?6) ON CONFLICT(ep) DO UPDATE SET tenant_id = excluded.tenant_id, uid = excluded.uid, p256dh = excluded.p256dh, auth = excluded.auth")
      .bind(b.endpoint, home, me.id, k.p256dh, k.auth, Date.now()).run();
    return json({ ok: true });
  }
  if (p === "unsub") {
    if (typeof b.endpoint === "string") await env.DB.prepare("DELETE FROM p_push WHERE ep = ?1 AND tenant_id = ?2").bind(b.endpoint, me.home || me.tenant_id).run();
    else await env.DB.prepare("DELETE FROM p_push WHERE tenant_id = ?1 AND uid = ?2").bind(me.home || me.tenant_id, me.id).run();
    return json({ ok: true });
  }
  if (p === "test") {
    const adm = me.tenant_id === ADMIN_PUSH;   // 28 oct 2026: the admin's own phone
    const r = await pushTenant(env, me.home || me.tenant_id, adm ? { title: "404 Content · Avisos activados", body: "Así te llegarán las altas, los pagos y la actividad de tus clientes.", tag: "test", url: "/admin" } : { title: "Avisos activados", body: "Así te avisaremos cuando toque grabar.", tag: "test", url: "/app" }, me.id);
    return json({ ok: r.some((s) => s >= 200 && s < 300), sent: r.length });
  }
  return bad("nope", 404);
}
