// cron: from 9:00, the day's idea on the phone of whoever turned the notices on (once a day)
async function dailyContent(env) {
  const now = Date.now(), p = tzParts(now);
  if (p.h < 9 || p.h >= 21) return 0;
  const today = dayKey(now), tag = "hoy:" + today;
  const rows = (await env.DB.prepare("SELECT i.id, i.tenant_id, i.data FROM p_ideas i JOIN p_tenants t ON t.id = i.tenant_id WHERE t.status = 'active' AND i.day = ?1 AND i.status = 'idea' AND EXISTS (SELECT 1 FROM p_push s WHERE s.tenant_id = COALESCE(t.parent, t.id)) AND NOT EXISTS (SELECT 1 FROM p_usage u WHERE u.tenant_id = i.tenant_id AND u.day = ?2) ORDER BY i.tenant_id, i.ord LIMIT 60").bind(today, tag).all()).results || [];
  const done = new Set();
  for (const r of rows) {
    if (done.has(r.tenant_id) || done.size >= 20) continue;
    done.add(r.tenant_id);
    await env.DB.prepare("INSERT INTO p_usage (tenant_id, day, msgs) VALUES (?1, ?2, 1) ON CONFLICT(tenant_id, day) DO NOTHING").bind(r.tenant_id, tag).run();
    const d = jparse(r.data, {}), same = rows.filter((x) => x.tenant_id === r.tenant_id), n = same.length;   // 27 oct 2026: plans with several videos a day
    const body = n > 1 ? n + " vídeos: " + same.slice(0, 4).map((x) => "«" + (jparse(x.data, {}).titulo || "vídeo") + "»").join(", ") + ". Empieza por el primero: «" + String(d.gancho || "").slice(0, 70) + "»"
      : (d.titulo || "Tu vídeo de hoy") + (d.gancho ? ". Empieza con: «" + d.gancho.slice(0, 90) + "»" : "");
    await pushTenant(env, r.tenant_id, { title: n > 1 ? "Hoy toca grabar " + n + " vídeos" : "Hoy toca grabar", body: body.slice(0, 230), tag: "hoy", url: "/app#contenido/" + r.id });
  }
  return done.size;
}

