async function adminTenant(req, env, id, action) {
  const t = await tenantOf(env, id); if (!t) return bad("tenant", 404);
  const b = (await body(req, 5000)) || {};
  if (action === "invite") {
    const email = str(b.email, 160).toLowerCase() || t.email;
    if (!okEmail(email)) return bad("email");
    if (await env.DB.prepare("SELECT 1 FROM p_users WHERE email = ?1").bind(email).first()) return bad("exists", 409);
    return json({ link: base(env) + "/invitacion#" + (await makeToken(env, "invite", id, email, null, 24 * 14)) });
  }
  if (action === "reset") {
    const u = await env.DB.prepare("SELECT email FROM p_users WHERE tenant_id = ?1 ORDER BY created LIMIT 1").bind(id).first();
    if (!u) return bad("nouser", 404);
    return json({ email: u.email, link: base(env) + "/restablecer#" + (await makeToken(env, "reset", id, u.email, null, 48)) });
  }
  if (action === "edit") {
    if (b.status && !["active", "paused", "paused_billing", "closed"].includes(b.status)) return bad("status");
    if (b.status) await env.DB.prepare("UPDATE p_tenants SET status = ?1 WHERE id = ?2").bind(b.status, id).run();
    if ("note" in b) await env.DB.prepare("UPDATE p_tenants SET note = ?1 WHERE id = ?2").bind(str(b.note, 1000) || null, id).run();
    if (b.plan === "content" || b.plan === "partner") await env.DB.prepare("UPDATE p_tenants SET plan = ?1 WHERE id = ?2").bind(b.plan, id).run();   // the price in Stripe is changed there
    if (b.tier && Object.prototype.hasOwnProperty.call(TIERS, b.tier) && b.tier !== tierOf(t)) { const r = await changeTier(env, t, b.tier); if (r.error) return bad("stripe", 502); }   // 27 oct 2026: also in Stripe
    if (b.status === "closed") await env.DB.prepare("DELETE FROM p_sessions WHERE uid IN (SELECT id FROM p_users WHERE tenant_id = ?1)").bind(id).run();
    // 27 oct 2026: a main business takes its extra businesses with it (pause, back on, close); an extra one closed here leaves the account
    if (b.status && !t.parent) await env.DB.prepare("UPDATE p_tenants SET status = ?1 WHERE parent = ?2 AND status != 'closed'").bind(b.status, id).run();
    if (b.status === "closed" && t.parent) { await env.DB.prepare("UPDATE p_sessions SET tenant = NULL WHERE tenant = ?1").bind(id).run(); if (t.stripe_item && t.stripe_sub) await stripe(env, "DELETE", "subscription_items/" + t.stripe_item + "?proration_behavior=none"); }
    return json({ ok: true });
  }
  return bad("action", 404);
}
async function adminSite(req, env, id) {
  const t = await tenantOf(env, id); if (!t) return bad("tenant", 404);
  const b = await body(req, 5000); if (!b) return bad("body");
  const s = await env.DB.prepare("SELECT data, status, updated FROM p_site WHERE tenant_id = ?1").bind(id).first();
  if (!s) return bad("site", 404);
  if (s.status !== "revision") return bad("not_review", 409);
  if (b.updated !== undefined && Number(b.updated) !== s.updated) return bad("changed", 409);   // the client changed it after you looked
  if (b.action === "approve") {
    await env.DB.prepare("UPDATE p_site SET status = 'publicada', live = data, published = ?1, review_note = NULL WHERE tenant_id = ?2").bind(Date.now(), id).run();
    await evt(env, "t_web", id, "Tu web ya está publicada: " + base(env) + "/s/" + t.slug);
    return json({ ok: true, url: base(env) + "/s/" + t.slug });
  }
  if (b.action === "reject") {
    const note = str(b.note, 1500); if (!note) return bad("note");
    await env.DB.prepare("UPDATE p_site SET status = 'cambios', review_note = ?1 WHERE tenant_id = ?2").bind(note, id).run();
    await evt(env, "t_web", id, "Hemos revisado tu web y te pedimos unos cambios: " + note);
    return json({ ok: true });
  }
  return bad("action");
}

/* ---------- every five minutes: follow-ups to people who stopped answering, appointment reminders, notices to the owner's phone,
   Instagram tokens, the subscriptions, the content plans («hoy toca grabar» included) and some cleaning ---------- */
const FOLLOW = "[Nota interna, no es de la persona: no ha respondido a tu último mensaje. Escribe UN mensaje corto de seguimiento, amable y sin presionar, que retome lo último que hablasteis y le ofrezca ayuda o un par de huecos. No vuelvas a presentarte. Si ya tiene cita o dijo que no le interesa, responde solo: NADA]";
async function followups(env) {
  const now = Date.now();
  const rows = (await env.DB.prepare("SELECT l.*, t.prefs AS tprefs, t.name AS tname FROM p_leads l JOIN p_tenants t ON t.id = l.tenant_id WHERE t.status = 'active' AND l.bot = 1 AND (l.handoff IS NULL OR l.handoff < ?1) AND l.stage IN ('nuevo', 'conversando') AND l.channel IN ('wa', 'ig') AND l.last_out > l.last_in AND l.last_in > ?2 AND l.followups < 3 ORDER BY l.last_out LIMIT 40")
    .bind(now, now - 7 * DAY).all()).results || [];
  let n = 0;
  const hr = tzParts(now).h;
  if (hr < 9 || hr >= 21) return 0;   // nobody gets a follow-up at night
  for (const l of rows) {
    const p = Object.assign({}, PREF_DEFAULT, jparse(l.tprefs, {})), f = p.followups || PREF_DEFAULT.followups;
    if (!f.on) continue;
    const inWin = now - l.last_in < DAY - 20 * 60000;
    const due = (l.followups === 0 && now - l.last_out >= 3 * 3600000 && f.max >= 1) || (l.followups === 1 && now - l.last_in >= 21 * 3600000 && f.max >= 2);
    if (inWin && due) {
      await env.DB.prepare("UPDATE p_leads SET followups = followups + 1 WHERE id = ?1").bind(l.id).run();   // counted first: a failure is not retried in a loop
      const tenant = await tenantOf(env, l.tenant_id), train = await getTrain(env, l.tenant_id);
      if (train.asistente && train.asistente.activo === false) continue;
      const msgs = ((await env.DB.prepare("SELECT dir, who, body, ts FROM p_msgs WHERE lead_id = ?1 ORDER BY ts DESC LIMIT 20").bind(l.id).all()).results || []).reverse();
      const turns = toTurns(msgs); turns.push({ role: "user", content: FOLLOW });
      const out = await think(env, { tenant, train, lead: l, channel: l.channel, appts: [] }, turns);
      const text = clean(out.text);
      if (!text || /^NADA\b/i.test(text)) continue;
      const sent = await sendTo(env, tenant, l, text);
      if (sent.ok) { await saveMsg(env, l.tenant_id, l.id, "out", "bot", l.channel, text, sent.ext); await env.DB.prepare("UPDATE p_leads SET last_out = ?1 WHERE id = ?2").bind(Date.now(), l.id).run(); n++; }
    } else if (!inWin && f.template && l.channel === "wa" && l.followups < 3 && now - l.last_in >= 3 * DAY && now - l.last_in < 6 * DAY) {
      await env.DB.prepare("UPDATE p_leads SET followups = 3 WHERE id = ?1").bind(l.id).run();   // the paid template goes once
      const train = await getTrain(env, l.tenant_id), bn = (train.negocio && train.negocio.nombre) || l.tname;
      const sent = await waTemplate(env, l.tenant_id, l.phone, "p404_retomar", [String(l.name || "").split(" ")[0] || "hola", bn]);
      if (sent.ok) { await saveMsg(env, l.tenant_id, l.id, "out", "bot", "wa", "Hola " + (String(l.name || "").split(" ")[0] || "") + ", soy el asistente virtual de " + bn + ". ¿Seguimos con lo que hablamos? Si quieres, te busco un hueco esta semana. (plantilla)", sent.ext); n++; }
    }
  }
  return n;
}
async function reminders(env) {
  const now = Date.now();
  const rows = (await env.DB.prepare("SELECT a.*, t.prefs AS tprefs, t.name AS tname FROM p_appts a JOIN p_tenants t ON t.id = a.tenant_id WHERE t.status = 'active' AND a.status = 'ok' AND a.reminded = 0 AND a.start > ?1 AND a.start < ?2 AND a.created < ?3 LIMIT 40").bind(now + 3600000, now + DAY, now - 2 * 3600000).all()).results || [];
  let n = 0;
  for (const a of rows) {
    await env.DB.prepare("UPDATE p_appts SET reminded = 1 WHERE id = ?1").bind(a.id).run();
    const p = Object.assign({}, PREF_DEFAULT, jparse(a.tprefs, {}));
    if (!(p.reminders || {}).on) continue;
    const train = await getTrain(env, a.tenant_id), bn = (train.negocio && train.negocio.nombre) || a.tname, first = String(a.name || "").split(" ")[0] || "hola";
    const lead = a.lead_id ? await env.DB.prepare("SELECT * FROM p_leads WHERE id = ?1").bind(a.lead_id).first() : null;
    const text = "Hola " + first + ", te recordamos tu cita en " + bn + " el " + human(a.start) + ". Si necesitas cambiarla, respóndenos por aquí.";
    let sent = { error: "none" };
    if (lead && (lead.channel === "wa" || lead.channel === "ig") && lead.last_in && now - lead.last_in < DAY - 600000) sent = await sendTo(env, await tenantOf(env, a.tenant_id), lead, text);
    else if ((lead && lead.phone) || a.phone) sent = await waTemplate(env, a.tenant_id, (lead && lead.phone) || a.phone, "p404_recordatorio", [first, bn, human(a.start)]);
    if (sent.ok) { if (lead) await saveMsg(env, a.tenant_id, lead.id, "out", "bot", lead.channel === "ig" ? "ig" : "wa", text, sent.ext); n++; }
  }
  return n;
}
