async function cron(env) {
  await pReady(env);
  const out = {}, step = async (k, fn) => { try { out[k] = await fn(env); } catch (e) { out[k] = "error: " + String(e && e.message).slice(0, 200); } };
  await step("reminders", reminders);
  await step("followups", followups);
  await step("avisos", avisos);
  await step("subs", checkSubs);
  await step("ig", igRefresh);
  await step("ideas", weeklyIdeas);
  await step("hoy", dailyContent);
  if (new Date().getUTCMinutes() < 5) await step("cleanup", cleanup);
  await step("actividad", actCron);
  await step("admin", adminPush);   // 28 oct 2026: the notices of the 404 Content admin on Chris's phone   // 27 oct 2026: three days without coming in during the trial; retention
  return out;
}

