function corsOf(req, env) {
  const o = req.headers.get("origin") || "";
  return origins(env).includes(o) ? { "access-control-allow-origin": o, "access-control-allow-methods": "POST, OPTIONS", "access-control-allow-headers": "content-type, x-404", "access-control-allow-credentials": "true", "access-control-max-age": "86400", vary: "origin" } : {};
}

/* ---------- the routes ---------- */
// what only Partner 404 has (a 404 Content session gets 403 «plan» there)
const PARTNER_ONLY = /^(leads(\.csv)?|lead(\/.*)?|appts|appt\/.*|slots|test|prefs|agenda|site(\/.*)?|wa\/connect|conn\/.*|home)$/;
/* 27 oct 2026: 404-content.com is the platform's home. www goes to it; app.404growth.com sends its pages there (webhooks, the API and the
   demo still answer on both, so nothing set up elsewhere breaks). The landing (made in the 404growth.com site, with its images) is served
   at 404-content.com/ straight from there, so there is one copy of it. */
const LANDING_FILES = /^\/(content-img\/[\w.-]+\.(webp|jpg|png)|logo-content(-wide)?\.(svg|png)|og-content\.png|inter-tight\.woff2|bricolage-display\.woff2|favicon\.ico)$/;
async function fromMain(req, ctx, p) {
  const cache = caches.default, key = new Request(MAIN + p);
  let r = await cache.match(key);
  if (!r) {
    const f = await fetch(MAIN + p, { headers: { "user-agent": "404Content-proxy" } });
    if (!f.ok) return new Response("No existe.", { status: f.status === 404 ? 404 : 502, headers: { "content-type": "text/plain; charset=utf-8" } });
    const h = new Headers(f.headers); h.set("cache-control", p === "/content" ? "public, max-age=300" : "public, max-age=86400"); h.delete("set-cookie");
    r = new Response(f.body, { status: 200, headers: h });
    if (ctx && ctx.waitUntil) ctx.waitUntil(cache.put(key, r.clone()));
  }
  return r;
}
async function route(req, env, ctx) {
  const url = new URL(req.url), path = url.pathname, M = req.method;
  if (!env.DEV) {
    if (url.hostname === "www.404-content.com") return new Response("", { status: 301, headers: { location: SITE + path + url.search } });
    const api = path.startsWith("/api/") || path.startsWith("/admin/api/") || /^\/(wa|ig|meta)\//.test(path) || path.startsWith("/demo") || path === "/c/e" || path.startsWith("/m/") || path.startsWith("/s/") || path === "/sw.js";
    if (url.hostname === "app.404growth.com" && M === "GET" && !api) return new Response("", { status: 301, headers: { location: SITE + path + url.search } });
    if (url.hostname === "404-content.com" && M === "GET") {
      if (path === "/" || path === "/index.html") return fromMain(req, ctx, "/content");
      if (path === "/content") return new Response("", { status: 301, headers: { location: SITE + "/" + url.search } });
      if (LANDING_FILES.test(path)) return fromMain(req, ctx, path);
    }
  }
  if (path === "/f/inter-tight.woff2") return font(req, ctx);
  if (path.startsWith("/m/")) return media(env, path.slice(3));
  if (path === "/demo") return demo(req, env);
  if (path === "/demo/ideas") return demoIdeas(req, env);
  if (path === "/c/e") return funnelEvt(req, env);
  if (path === "/sw.js") return new Response(SW_JS, { headers: { "content-type": "application/javascript; charset=utf-8", "cache-control": "no-cache", "service-worker-allowed": "/" } });
  if (path === "/icon-192.png" || path === "/icon-512.png" || path === "/apple-touch-icon.png") return new Response(unb64(path === "/icon-512.png" ? ICON_512 : path === "/icon-192.png" ? ICON_192 : ICON_180), { headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" } });
  if (path === "/wa/webhook" || path === "/ig/webhook") {
    if (M === "GET") return verifyHook(env, url);
    if (M !== "POST") return new Response("", { status: 405 });
    const raw = await req.text();
    if (raw.length > 1000000 || !(await metaSigned(env, req, raw))) return new Response("bad signature", { status: 401 });
    const payload = jparse(raw, {});
    ctx.waitUntil((path === "/wa/webhook" || payload.object === "whatsapp_business_account" ? waHook(env, payload) : igHook(env, payload)).catch((e) => console.log("hook", e && e.stack)));
    return new Response("ok", { status: 200 });
  }
  if (path === "/ig/callback") return igCallback(req, env, url);
  if (path === "/meta/deauth") return metaCallback(req, env, "deauth");
  if (path === "/meta/delete") return metaCallback(req, env, "delete");
  const me = await session(req, env);
  if (path === "/api/ig/start" && M === "GET") return me && me.kind === "c" && me.plan !== "content" ? igStart(req, env, me) : go(me ? "/app" : "/entrar");
  if (path.startsWith("/s/")) { const [slug, rest] = path.slice(3).split("/"); return sitePublic(req, env, slug, rest || "", me); }

  // pages
  if (M === "GET" && !path.startsWith("/api/") && !path.startsWith("/admin/api/")) {
    if (path === "/") return go(me ? (me.kind === "a" ? "/admin" : "/app") : MAIN + "/content");
    if (path === "/app") return me && me.kind === "c" ? page(PAGES.app) : go("/entrar");
    if (path === "/admin") return me && me.kind === "a" ? page(PAGES.admin) : go("/entrar?admin=1");
    if (path === "/admin/invitacion") return page(PAGES.link);   // 29 oct 2026: an invitation to the 404 Content admin
    if (path === "/entrar") return page(PAGES.login);
    if (path === "/empezar") return page(PAGES.start);
    if (path === "/bienvenida") return page(PAGES.welcome);
    if (path === "/invitacion" || path === "/restablecer") return page(PAGES.link);
    if (path === "/condiciones") return page(PAGES.terms, null, { "cache-control": "public, max-age=300" });
    if (path === "/privacidad") return page(PAGES.privacy, null, { "cache-control": "public, max-age=300" });
    if (path === "/eliminar-datos") return page(PAGES.deletion, null, { "cache-control": "public, max-age=300" });
    if (path === "/admin.webmanifest") {   // 27 oct 2026: the admin as its own app on Chris's phone (start /admin, its own name and icon)
      return new Response(JSON.stringify({ name: "404 Content Admin", short_name: "404 Admin", id: "/admin", start_url: "/admin", scope: "/admin", display: "standalone", background_color: "#F5F5F7", theme_color: "#FFFFFF", lang: "es",
        icons: [{ src: "/icon-192.png", sizes: "192x192", type: "image/png" }, { src: "/icon-512.png", sizes: "512x512", type: "image/png" }, { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }] }), { headers: { "content-type": "application/manifest+json", "cache-control": "public, max-age=3600" } });
    }
    if (path === "/manifest.webmanifest") {   // the app on the phone's home screen is called as the client's plan
      const t = me && me.kind === "c" ? await tenantOf(env, me.tenant_id) : null, nm = "404 Content";
      return new Response(JSON.stringify({ name: nm, short_name: nm, id: "/app", start_url: "/app", scope: "/", display: "standalone", background_color: "#FFFFFF", theme_color: "#FFFFFF", lang: "es",
        icons: [{ src: "/icon-192.png", sizes: "192x192", type: "image/png" }, { src: "/icon-512.png", sizes: "512x512", type: "image/png" }, { src: "/icon.svg", sizes: "any", type: "image/svg+xml" }] }), { headers: { "content-type": "application/manifest+json", "cache-control": "private, max-age=600" } });
    }
    if (path === "/icon.svg") return new Response('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#6E56FF"/><stop offset=".52" stop-color="#FF3D8B"/><stop offset="1" stop-color="#FF9F1C"/></linearGradient></defs><rect width="40" height="40" rx="11" fill="url(#g)"/><text x="20" y="25.4" text-anchor="middle" font-family="-apple-system,BlinkMacSystemFont,Helvetica Neue,Arial,sans-serif" font-weight="800" font-size="15" letter-spacing="-0.5" fill="#fff">404</text></svg>', { headers: { "content-type": "image/svg+xml", "cache-control": "public, max-age=86400" } });
    return new Response("No existe.", { status: 404, headers: { "content-type": "text/plain; charset=utf-8" } });
  }

  // public API
  if (M === "POST") {
    if (path === "/api/login") return login(req, env);
    if (path === "/api/logout") return logout(req, env);
    if (path === "/api/checkout") return checkout(req, env);
    if (path === "/api/welcome") return welcome(req, env);
    if (path === "/api/link") return acceptLink(req, env);
    if (path === "/api/forgot") return forgot(req, env);
  }
  if (M === "POST" && !ours(req, env)) return bad("origin", 403);

  // Chris
  if (path.startsWith("/admin/api/")) {
    if (!me || me.kind !== "a") return bad("auth", 401);
    const p = path.slice(11);
    if (M === "GET" && p === "overview") return adminOverview(env, me);
    /* 29 oct 2026: a 404 Content-only admin: no keys, no access management, no Partner 404 */
    if (me.scope === "content") {
      if (p.startsWith("access") || p.startsWith("site/")) return bad("scope", 403);   // the keys of 404 Content he can change (adminCfg)
      const tm = /^tenant\/(pt_[A-Za-z0-9_-]{12})\//.exec(p);
      if (tm) { const tt = await tenantOf(env, tm[1]); if (!tt || planOf(tt) !== "content") return bad("nope", 404); }
    }
    if (M === "GET" && p === "access") return adminAccess(req, env, me, "list");
    if (M === "POST" && p === "access") return adminAccess(req, env, me, "invite");
    if (M === "POST" && p.startsWith("access/")) return adminAccess(req, env, me, p.slice(7));
    if (M === "POST" && p === "cfg") return adminCfg(req, env, me);
    if (M === "POST" && p === "check") return adminCheck(env);
    if (M === "POST" && p === "tenant") return adminTenantNew(req, env);
    let m;
    if (M === "POST" && (m = /^tenant\/(pt_[A-Za-z0-9_-]{12})\/(invite|reset|edit)$/.exec(p))) return adminTenant(req, env, m[1], m[2]);
    if (M === "POST" && (m = /^site\/(pt_[A-Za-z0-9_-]{12})$/.exec(p))) return adminSite(req, env, m[1]);
    if (M === "GET" && (m = /^tenant\/(pt_[A-Za-z0-9_-]{12})\/activity$/.exec(p))) return adminActivity(env, m[1]);   // 27 oct 2026
    if (M === "GET" && p === "push/key") return adminPushApi(req, env, me, "key");   // 28 oct 2026: the admin's notices
    if (M === "POST" && (m = /^push\/(sub|unsub|test)$/.exec(p))) return adminPushApi(req, env, me, m[1]);
    return bad("nope", 404);
  }

  // the client's panel
  if (!path.startsWith("/api/")) return bad("nope", 404);
  if (!me || me.kind !== "c") return bad("auth", 401);
  const p = path.slice(5);
  /* 27 oct 2026: what the client does in the panel (15-activity.js): the panel's own signals, and each API call that went well */
  if (M === "POST" && p === "act") return apiAct(req, env, me);
  if (M === "POST") { try { await ideaActOf(req, env, me, p); } catch (e) { /* only the label of the action */ } }
  const res = await clientApi(req, env, me, p, M, url);
  if (res.status < 400) { const w = actAfter(env, me, M, p, res.clone()).catch((e) => console.log("act", e && e.message)); if (ctx && ctx.waitUntil) ctx.waitUntil(w); else await w; }
  return res;
}
async function clientApi(req, env, me, p, M, url) {
  let m;
  if (me.plan === "content" && PARTNER_ONLY.test(p)) return bad("plan", 403);   // 404 Content has no assistant, CRM, agenda or web
  if (M === "GET") {
    if (p === "me") return apiMe(env, me);
    if (p === "home") return apiHome(env, me);
    if (p === "leads") return apiLeads(env, me, url);
    if (p === "leads.csv") return apiCsv(env, me);
    if ((m = /^lead\/(pl_[A-Za-z0-9_-]{12})$/.exec(p))) return apiLead(env, me, m[1]);
    if (p === "appts") return apiAppts(env, me, url);
    if (p === "slots") return apiSlots(env, me, url);
    if (p === "train") return apiTrain(req, env, me);
    if (p === "ideas") return apiIdeas(env, me);
    if (p === "captions") return apiCaptionList(env, me);
    if (p === "push/key") return apiPush(req, env, me, "key");
    if (p === "interview") return apiInterview(req, env, me, p, M);   // 27 oct 2026 (17-entrevista.js)
    if (p === "biz") return json(await bizInfo(env, me));   // 27 oct 2026 (16-negocios.js)
    if (p === "site") return apiSite(req, env, me);
    return bad("nope", 404);
  }
  if (M !== "POST") return bad("method", 405);
  if (p === "train") return apiTrain(req, env, me);
  if (p === "agenda") return apiAgenda(req, env, me);
  if (p === "test") return apiTest(req, env, me);
  if (p === "prefs") return apiPrefs(req, env, me);
  if (p === "brand") return apiBrand(req, env, me);
  if (p === "lead") return apiLeadNew(req, env, me);
  if ((m = /^lead\/(pl_[A-Za-z0-9_-]{12})(?:\/(send|delete))?$/.exec(p))) return m[2] === "send" ? apiLeadSend(req, env, me, m[1]) : m[2] === "delete" ? apiLeadDelete(env, me, m[1]) : apiLeadEdit(req, env, me, m[1]);
  if (p === "appts") return apiApptNew(req, env, me);
  if ((m = /^appt\/(pa_[A-Za-z0-9_-]{12})$/.exec(p))) return apiApptEdit(req, env, me, m[1]);
  if (p === "ideas") return apiIdeasGen(env, me);
  if ((m = /^idea\/(pi_[A-Za-z0-9_-]{12})(\/redo)?$/.exec(p))) return m[2] ? apiIdeaRedo(env, me, m[1]) : apiIdeaEdit(req, env, me, m[1]);
  if (p === "profile/scan") return apiScan(req, env, me);
  if (p === "captions") return apiCaptions(req, env, me);
  if ((m = /^caption\/(pc_[A-Za-z0-9_-]{12})\/delete$/.exec(p))) return apiCaptionDelete(env, me, m[1]);
  if ((m = /^push\/(sub|unsub|test)$/.exec(p))) return apiPush(req, env, me, m[1]);
  if (p === "upgrade") return apiUpgrade(env, me);
  if (p === "site") return apiSite(req, env, me);
  if (p === "site/photo") return apiSitePhoto(req, env, me);
  if (p === "site/submit") return apiSiteSubmit(env, me);
  if (p === "site/write") return apiSiteWrite(env, me);
  if (p === "wa/connect") return waConnect(req, env, me);
  if ((m = /^conn\/(wa|ig)\/delete$/.exec(p))) return apiConnDelete(env, me, m[1]);
  if (p === "billing") return portal(req, env, me);
  if (p === "tier") return apiTier(req, env, me);   // 27 oct 2026: videos a day
  if (/^interview\/(next|answer|stop|forget)$/.test(p)) return apiInterview(req, env, me, p, M);   // 27 oct 2026: the interview
  if (p === "biz") return apiBizAdd(req, env, me);   // 27 oct 2026: a 2nd or 3rd business
  if (p === "biz/switch") return apiBizSwitch(req, env, me);
  if ((m = /^biz\/(pt_[A-Za-z0-9_-]{12})\/delete$/.exec(p))) return apiBizDelete(req, env, me, m[1]);
  if (p === "password") return changePassword(req, env, me);
  return bad("nope", 404);
}

export default {
  async fetch(req, env, ctx) {
    try { await pReady(env); return await route(req, env, ctx); }
    catch (e) { console.log("error", e && e.stack); return json({ error: "server" }, 500); }
  },
  async scheduled(event, env, ctx) { ctx.waitUntil(cron(env)); },
};

/* the app icon: the 404 Content mark, «404» on the gradient (full square: phones round the corners) */
const ICON_180 = "";
const ICON_192 = "";
const ICON_512 = "";

/* ---------- what each client does in their panel (27 oct 2026) ----------
   Chris: «necesito ampliar el traqueo de las acciones que hacen … cada persona dentro de la plataforma 404 content». Every action is a row
   in p_act (tenant, time, type, a short label, a number, where it came from: server or panel). The server writes the actions that go
   through the API (profile saved, web read, ideas made, an idea recorded, a video uploaded, notices on, billing opened…), checked after
   they succeed; the panel adds what only it sees (which part is open, an idea opened, a text copied, active time), through /api/act,
   with a catalogue, short labels and limits. Nothing typed by the client is kept here, only that it happened. Some moments are
   milestones and reach Chris's phone once (kind c_act in p_events, which the 404 admin turns into a push): first time in the panel,
   profile ready, first calendar, first video recorded, first texts, notices on, billing opened (maybe to cancel, once a day), three
   days without coming in during the trial. Kept 365 days. */
const ACT_DDL = ["CREATE TABLE IF NOT EXISTS p_act (id INTEGER PRIMARY KEY AUTOINCREMENT, tenant_id TEXT NOT NULL, ts INTEGER NOT NULL, y TEXT NOT NULL, l TEXT, n INTEGER, src TEXT NOT NULL DEFAULT 'server')",
  "CREATE INDEX IF NOT EXISTS p_act_t ON p_act (tenant_id, ts)"];
const ACT_TXT = {
  open: "Entra en su panel", view: "Abre", idea_open: "Abre la idea", copy: "Copia el texto de", time: "Tiempo activo en el panel",
  profile: "Guarda su perfil", scan: "Lee su web para rellenar el perfil", brand: "Cambia su marca", prefs: "Cambia sus preferencias",
  ideas: "Pide un mes de ideas", idea_redo: "Pide otra versión de una idea", idea_rec: "Marca como grabada", idea_pub: "Marca como publicada", idea_skip: "Descarta una idea", idea_move: "Mueve una idea a otro día",
  captions: "Sube un vídeo y recibe sus textos", caption_del: "Borra los textos de un vídeo", push_on: "Activa los avisos", push_off: "Quita los avisos", push_test: "Prueba los avisos",
  billing: "Abre facturación (tarjeta, facturas o cancelar)", password: "Cambia su contraseña",
  interview_start: "Empieza la entrevista con la IA", interview: "Contesta una pregunta de la entrevista", interview_voice: "Contesta la entrevista con una nota de voz",
  biz_add: "Añade un negocio a su cuenta", biz_del: "Quita un negocio de su cuenta", biz_switch: "Cambia de negocio en el panel",
};
const ACT_VIEWS = ["inicio", "calendario", "videos", "textos", "negocio", "ajustes", "mas", "contenido", "entrevista"];
async function actLog(env, tenantId, y, l, n, src) {
  try { await env.DB.prepare("INSERT INTO p_act (tenant_id, ts, y, l, n, src) VALUES (?1, ?2, ?3, ?4, ?5, ?6)").bind(tenantId, Date.now(), y, l ? String(l).slice(0, 80) : null, n == null ? null : n, src || "server").run(); }
  catch (e) { console.log("act", e && e.message); }
}
/* a milestone reaches Chris once (or once a day for billing) */
async function milestone(env, t, key, text) {
  const k = "ms:" + t.id + ":" + key;
  const r = await env.DB.prepare("INSERT OR IGNORE INTO p_cfg (k, v) VALUES (?1, ?2)").bind(k, String(Date.now())).run();
  if (r.meta && r.meta.changes) await evt(env, "c_act", t.id, t.name + ": " + text);
}
async function tenantName(env, id) { return (await env.DB.prepare("SELECT id, name, sub_status FROM p_tenants WHERE id = ?1").bind(id).first()) || { id, name: "Cliente" }; }

/* after a client API call that went well: what it was */
async function actAfter(env, me, M, p, res) {
  if (!res || res.status >= 400 || me.kind !== "c") return;
  let y = null, l = null, n = null, j = null;
  const J = async () => { if (j === null) { try { j = await res.clone().json(); } catch (e) { j = {}; } } return j; };
  if (M === "GET" && p === "me") {   /* coming into the panel: once per 30 min */
    const last = await env.DB.prepare("SELECT ts FROM p_act WHERE tenant_id = ?1 AND y = 'open' ORDER BY id DESC LIMIT 1").bind(me.tenant_id).first();
    if (last && Date.now() - last.ts < 30 * 60000) return;
    y = "open";
  }
  if (M === "POST") {
    if (p === "train") { y = "profile"; n = (await J()).progress; }
    else if (p === "profile/scan") { y = "scan"; n = ((await J()).filled || []).length; }
    else if (p === "brand") y = "brand";
    else if (p === "prefs") y = "prefs";
    else if (p === "ideas") { y = "ideas"; n = ((await J()).ideas || []).length || null; }
    else if (/^idea\/pi_[A-Za-z0-9_-]{12}\/redo$/.test(p)) y = "idea_redo";
    else if (/^idea\/pi_[A-Za-z0-9_-]{12}$/.test(p)) { y = me._ideaAct || null; l = me._ideaTitle || null; }
    else if (p === "captions") { y = "captions"; l = (await J()).title || null; }
    else if (/^caption\/pc_[A-Za-z0-9_-]{12}\/delete$/.test(p)) y = "caption_del";
    else if (p === "push/sub") y = "push_on"; else if (p === "push/unsub") y = "push_off"; else if (p === "push/test") y = "push_test";
    else if (p === "billing") y = "billing";
    else if (p === "password") y = "password";
    else if (p === "interview/next") y = "interview_start";
    else if (p === "interview/answer") { const r = await J(); y = r.heard ? "interview_voice" : "interview"; n = (r.learned || []).length; }
    else if (p === "biz") y = "biz_add"; else if (/^biz\/pt_[A-Za-z0-9_-]{12}\/delete$/.test(p)) y = "biz_del"; else if (p === "biz/switch") y = "biz_switch";
  }
  if (!y) return;
  await actLog(env, me.tenant_id, y, l, n == null ? null : Math.round(Number(n)) || 0, "server");
  const t = await tenantName(env, me.tenant_id);
  if (y === "open") await milestone(env, t, "first_open", "ha entrado en su panel por primera vez.");
  if ((y === "profile" || y === "scan") && (await env.DB.prepare("SELECT data FROM p_train WHERE tenant_id = ?1").bind(me.tenant_id).first())) {
    const tr = await env.DB.prepare("SELECT t.niche, r.data FROM p_tenants t LEFT JOIN p_train r ON r.tenant_id = t.id WHERE t.id = ?1").bind(me.tenant_id).first();
    if (tr && trainProgress(tr.niche, jparse(tr.data, {}), "content") >= 80) await milestone(env, t, "profile80", "tiene su perfil completo (80 % o más).");
  }
  if (y === "ideas") await milestone(env, t, "first_ideas", "ya tiene su primer calendario de vídeos.");
  if (y === "idea_rec") await milestone(env, t, "first_rec", "ha marcado su primer vídeo como grabado" + (l ? ": «" + l + "»" : "") + ".");
  if (y === "captions") await milestone(env, t, "first_caps", "ha subido su primer vídeo y tiene sus textos.");
  if (y === "push_on") await milestone(env, t, "push_on", "ha activado los avisos en el móvil.");
  if (y === "billing") await milestone(env, t, "billing:" + new Date().toISOString().slice(0, 10), "ha abierto facturación (tarjeta, facturas o cancelar)." + (t.sub_status === "trialing" ? " Está en la prueba: puede querer cancelar." : ""));
}
/* an idea edit: what kind of change it was (read before the API call changes it) */
async function ideaActOf(req, env, me, p) {
  const m = /^idea\/(pi_[A-Za-z0-9_-]{12})$/.exec(p); if (!m) return;
  let b = null; try { b = await req.clone().json(); } catch (e) { return; }
  if (!b || typeof b !== "object") return;
  const i = await env.DB.prepare("SELECT json_extract(data, '$.titulo') AS titulo, status, day FROM p_ideas WHERE id = ?1 AND tenant_id = ?2").bind(m[1], me.tenant_id).first(); if (!i) return;
  me._ideaTitle = i.titulo;
  if (b.status && b.status !== i.status) me._ideaAct = { grabado: "idea_rec", publicado: "idea_pub", descartada: "idea_skip" }[b.status] || null;
  else if (b.day && b.day !== i.day) me._ideaAct = "idea_move";
}
/* what only the panel sees: up to 20 a post, 1500 a day per client */
async function apiAct(req, env, me) {
  const b = await body(req, 8000); if (!b || !Array.isArray(b.ev)) return bad("body");
  const day = await env.DB.prepare("SELECT COUNT(*) AS n FROM p_act WHERE tenant_id = ?1 AND ts > ?2").bind(me.tenant_id, Date.now() - DAY).first();
  if (day && day.n >= 1500) return json({ ok: true, full: true });
  const q = [];
  for (const x of b.ev.slice(0, 20)) {
    if (!x || typeof x !== "object") continue;
    const l = typeof x.l === "string" ? x.l.replace(/[\u0000-\u001f]+/g, " ").trim().slice(0, 80) : null;
    if (x.y === "view" && ACT_VIEWS.includes(l)) q.push(["view", l, null]);
    else if (x.y === "idea_open" && l) q.push(["idea_open", l, null]);
    else if (x.y === "copy" && l && /^[\wÀ-ÿ ()·.-]{1,40}$/.test(l)) q.push(["copy", l, null]);
    else if (x.y === "time") { const n = Math.round(Number(x.n)); if (n > 0 && n <= 900) q.push(["time", null, n]); }
  }
  if (q.length) await env.DB.batch(q.map(([y, l, n]) => env.DB.prepare("INSERT INTO p_act (tenant_id, ts, y, l, n, src) VALUES (?1, ?2, ?3, ?4, ?5, 'panel')").bind(me.tenant_id, Date.now(), y, l, n)));
  return json({ ok: true, n: q.length });
}
/* the admin: one client's activity, newest first, with a summary */
async function adminActivity(env, id) {
  const t = await env.DB.prepare("SELECT id, name, created FROM p_tenants WHERE id = ?1").bind(id).first(); if (!t) return bad("tenant", 404);
  const rows = (await env.DB.prepare("SELECT ts, y, l, n, src FROM p_act WHERE tenant_id = ?1 ORDER BY id DESC LIMIT 400").bind(id).all()).results || [];
  const now = Date.now(), days7 = new Set(), days30 = new Set(); let time7 = 0, last = null;
  for (const r of rows) {
    const d = new Date(r.ts).toISOString().slice(0, 10);
    if (r.y !== "time" && (!last || r.ts > last)) last = r.ts;
    if (now - r.ts < 7 * DAY) { days7.add(d); if (r.y === "time") time7 += r.n || 0; }
    if (now - r.ts < 30 * DAY) days30.add(d);
  }
  const count = (y) => rows.filter((r) => r.y === y).length;
  return json({ now, tenant: t, summary: { last, days7: days7.size, days30: days30.size, time7, opens: count("open"), recorded: count("idea_rec"), videos: count("captions"), copies: count("copy") },
    items: rows.filter((r) => r.y !== "time").slice(0, 300).map((r) => ({ ts: r.ts, y: r.y, l: r.l, n: r.n, src: r.src, txt: ACT_TXT[r.y] || r.y })) });
}
/* cron (hourly): three days without coming in during the trial; and the retention */
async function actCron(env) {
  const now = Date.now(), lastRun = Number((await env.DB.prepare("SELECT v FROM p_cfg WHERE k = 'act_cron'").first() || {}).v || 0);
  if (now - lastRun < 55 * 60000) return "later";
  await env.DB.prepare("INSERT INTO p_cfg (k, v) VALUES ('act_cron', ?1) ON CONFLICT(k) DO UPDATE SET v = excluded.v").bind(String(now)).run();
  const T = (await env.DB.prepare("SELECT t.id, t.name, t.sub_status, t.created, (SELECT MAX(ts) FROM p_act a WHERE a.tenant_id = t.id AND a.y != 'time') AS last FROM p_tenants t WHERE t.status = 'active' AND t.sub_status = 'trialing' AND t.parent IS NULL").all()).results || [];
  let n = 0;
  for (const t of T) {
    const last = t.last || t.created;
    if (now - last > 3 * DAY) { await milestone(env, t, "idle3:" + new Date(last).toISOString().slice(0, 10), "lleva " + Math.floor((now - last) / DAY) + " días sin entrar en su prueba. Buen momento para escribirle."); n++; }
  }
  if (new Date(now).getUTCHours() === 3) await env.DB.prepare("DELETE FROM p_act WHERE ts < ?1").bind(now - 365 * DAY).run();
  return n;
}

/* ---------- 27 oct 2026: a 2nd and a 3rd business in the same account ----------
   Chris: «opción de meter un segundo o tercer negocio por cada negocio». Each business is its own tenant (profile, interview, calendar,
   video texts, brand, plan) hanging from the account's main one (p_tenants.parent). The user signs in once and switches from the panel; the
   session remembers which business is open (p_sessions.tenant). Each extra business pays its own plan (19, 29 or 49 €, IVA included), as one
   more line in the same Stripe subscription, on the same card: during the free week it goes into the first charge; after that, the next
   invoice carries the part of this month and then the full price each month. Taking one away removes its line from the next charge (nothing
   is refunded, as with the main plan). An account with no charge (made by Chris) adds them with no charge either. */
const MAX_BIZ = 3;
async function bizRows(env, home) {
  return (await env.DB.prepare("SELECT id, name, niche, tier, status, parent, created FROM p_tenants WHERE (id = ?1 OR parent = ?1) AND status != 'closed' ORDER BY parent IS NOT NULL, created").bind(home).all()).results || [];
}
async function bizInfo(env, me) {
  const home = me.home || me.tenant_id, rows = await bizRows(env, home);
  const tr = (await env.DB.prepare("SELECT tenant_id, data FROM p_train WHERE tenant_id IN (SELECT id FROM p_tenants WHERE id = ?1 OR parent = ?1)").bind(home).all()).results || [];
  const tipo = {}; for (const r of tr) { const d = jparse(r.data, {}); tipo[r.tenant_id] = (d.negocio && d.negocio.tipo) || ""; }
  return { max: MAX_BIZ, active: me.tenant_id, home,
    list: rows.map((t) => ({ id: t.id, name: t.name, tipo: tipo[t.id] || (NICHE[t.niche] || NICHE.general).label, tier: tierOf(t), price: TIERS[tierOf(t)].month, main: !t.parent, status: t.status })) };
}
// which business the panel shows: the main one (NULL) or one of its extra ones
async function setActive(req, env, me, id) {
  const home = me.home || me.tenant_id;
  if (id !== home && !(await env.DB.prepare("SELECT 1 FROM p_tenants WHERE id = ?1 AND parent = ?2 AND status != 'closed'").bind(id, home).first())) return false;
  await env.DB.prepare("UPDATE p_sessions SET tenant = ?1 WHERE h = ?2").bind(id === home ? null : id, await sha(cookieOf(req, env))).run();
  return true;
}
async function apiBizSwitch(req, env, me) {
  const b = await body(req, 500); if (!b || typeof b.id !== "string" || !/^pt_[A-Za-z0-9_-]{12}$/.test(b.id)) return bad("biz");
  if (!(await setActive(req, env, me, b.id))) return bad("biz", 404);
  return json({ ok: true, id: b.id });
}
// POST /api/biz {name, niche, web, tier}: a new business in this account, open in the panel straight away
async function apiBizAdd(req, env, me) {
  const b = await body(req, 3000); if (!b) return bad("body");
  const home = me.home || me.tenant_id, main = await tenantOf(env, home);
  if (!main || main.status === "closed") return bad("auth", 401);
  if (main.status !== "active") return bad("paused", 409);
  const name = str(b.name, 80), niche = NICHES.includes(b.niche) ? b.niche : "general", tier = tierKey(b.tier), T = TIERS[tier];
  if (name.length < 2) return bad("name");
  let web = str(b.web, 300);
  if (web && !/^https?:\/\//i.test(web)) web = "https://" + web;
  if (web) { try { const u = new URL(web); web = /^https?:$/.test(u.protocol) && u.hostname.includes(".") ? u.href : ""; } catch (e) { web = ""; } }
  if ((await bizRows(env, home)).length >= MAX_BIZ) return bad("max", 409);
  if (!(await bump(env, home, "biz", 6))) return bad("limit", 429);   // adding and taking away, a few times a day at most
  const id = rid("pt_");
  let item = null;
  if (main.stripe_sub) {   // its own line in the same subscription: its own name on the invoice and its own price
    const auto = (await cfg(env, "iva")) === "stripe_tax", txr = auto ? null : await ivaRateIncl(env);
    const prod = await stripe(env, "POST", "products", { name: "404 Content · " + name + " (negocio extra)", metadata: { tenant: id } });
    if (!prod || !prod.id) return bad("stripe", 502);
    const it = await stripe(env, "POST", "subscription_items", { subscription: main.stripe_sub, quantity: 1, proration_behavior: "create_prorations", tax_rates: txr ? [txr] : undefined,
      price_data: { currency: PRICE.currency, product: prod.id, unit_amount: T.month, recurring: { interval: "month" }, tax_behavior: auto ? "inclusive" : undefined }, metadata: { tenant: id, negocio: name, tier } });
    if (!it || !it.id) return bad("stripe", 502);
    item = it.id;
  }
  await newTenant(env, { id, name, niche, email: main.email, phone: prefsOf(main).owner_phone || "", status: "active", customer: main.stripe_customer, sub: main.stripe_sub, plan: "content", web, tier,
    parent: main.id, item, subStatus: main.sub_status || (main.stripe_sub ? "trialing" : "free"), free: !main.stripe_sub });
  await setActive(req, env, me, id);
  await evt(env, "c_biz", main.id, main.name + " añade un negocio a su cuenta: " + name + " (" + T.label + ", " + (main.stripe_sub ? T.month / 100 + " €/mes, IVA incluido, en su misma suscripción" : "sin cobro, como su cuenta") + ").");
  return json({ ok: true, id, charged: !!main.stripe_sub, price: T.month, biz: await bizInfo(env, Object.assign({}, me, { tenant_id: id })) });
}
// POST /api/biz/<id>/delete: an extra business leaves the account (its line leaves the subscription from the next charge)
async function apiBizDelete(req, env, me, id) {
  const home = me.home || me.tenant_id;
  const t = await env.DB.prepare("SELECT * FROM p_tenants WHERE id = ?1 AND parent = ?2 AND status != 'closed'").bind(id, home).first();
  if (!t) return bad("biz", 404);
  if (!(await bump(env, home, "biz", 6))) return bad("limit", 429);
  if (t.stripe_item && t.stripe_sub) {
    const r = await stripe(env, "DELETE", "subscription_items/" + t.stripe_item + "?proration_behavior=none");
    if (!r || (!r.deleted && r._status !== 404)) return bad("stripe", 502);
  }
  await env.DB.batch([
    env.DB.prepare("UPDATE p_tenants SET status = 'closed', stripe_item = NULL WHERE id = ?1").bind(id),
    env.DB.prepare("UPDATE p_sessions SET tenant = NULL WHERE tenant = ?1").bind(id),
  ]);
  await evt(env, "c_biz", home, t.name + " deja la cuenta de " + ((await tenantOf(env, home)) || {}).name + (t.stripe_item ? ": sale de su suscripción desde el próximo cobro." : "."));
  return json({ ok: true, biz: await bizInfo(env, Object.assign({}, me, { tenant_id: me.tenant_id === id ? home : me.tenant_id })) });
}

/* ---------- 27 oct 2026: the interview, so the AI knows the whole business and not only what its web says ----------
   Chris: «facilidad para que la IA tenga toda la info del negocio, no solamente saque scrapeando su web una vez dentro». In «Tu negocio» the
   AI asks the owner one question at a time, as in a chat (what sells most and at what price, the usual client, why they choose this business,
   the questions and doubts it hears, the team, its story, what can be shown of the day to day, real cases, seasons, what not to film, how it
   talks). The owner answers writing or with a voice note (Workers AI writes it down, as with the videos). Each answer fills the empty parts of
   the profile (services, frequent questions, audience, what to avoid, the niche's own fields…) and leaves short facts in train.saber, which
   every idea, calendar and video text reads (trainText). About twelve questions a round; it can stop and go on any time, and later ask more.
   Each answer is one call to the model, with the whole profile, what was asked already and a forced tool, so the output is always readable. */
const INT_DDL = ["CREATE TABLE IF NOT EXISTS p_interview (tenant_id TEXT PRIMARY KEY, data TEXT NOT NULL, updated INTEGER NOT NULL)"];
const INT_ROUND = 12, INT_FACTS = 150;
const knowInfo = (train) => ({ facts: (Array.isArray(train && train.saber) ? train.saber : []).length });
async function intGet(env, tid) { const r = await env.DB.prepare("SELECT data FROM p_interview WHERE tenant_id = ?1").bind(tid).first(); const d = r ? jparse(r.data, {}) : {}; d.qa = Array.isArray(d.qa) ? d.qa : []; return d; }
const intPut = (env, tid, d) => env.DB.prepare("INSERT INTO p_interview (tenant_id, data, updated) VALUES (?1, ?2, ?3) ON CONFLICT(tenant_id) DO UPDATE SET data = excluded.data, updated = excluded.updated").bind(tid, JSON.stringify(d), Date.now()).run();
function intTool(niche) {
  const n = NICHE[niche] || NICHE.general, ex = {};
  for (const x of n.extra) ex[x.k] = { type: "string", description: x.l };
  return { name: "entrevista", description: "Guarda lo que ha contado el dueño y haz la siguiente pregunta.", input_schema: { type: "object", required: ["hechos", "siguiente", "terminado"], properties: {
    hechos: { type: "array", items: { type: "string" }, description: "Lo que has aprendido con su última respuesta, en frases cortas y concretas, en tercera persona y con sus datos reales («Lo que más venden es el balayage, desde 85 €»). Vacío si no ha contado nada nuevo." },
    actualizar: { type: "object", description: "Solo lo que su respuesta diga de forma clara. Nada inventado.", properties: {
      tipo: { type: "string", description: "Qué tipo de negocio es, en 2 a 4 palabras" }, ciudad: { type: "string", description: "Ciudad y barrio" },
      sobre: { type: "string", description: "Quiénes son, en primera persona del plural" }, publico: { type: "string", description: "A quién quieren llegar: su cliente típico" },
      evitar: { type: "string", description: "Lo que no quieren en sus vídeos" }, redes: { type: "string", description: "Dónde publican" },
      tono: { type: "string", enum: Object.keys(TONOS), description: "Cómo hablan a sus clientes" },
      servicios: { type: "array", items: { type: "object", required: ["nombre"], properties: { nombre: { type: "string" }, precio: { type: "string" }, nota: { type: "string" } } } },
      preguntas: { type: "array", description: "Dudas de sus clientes con la respuesta que da el negocio", items: { type: "object", required: ["p", "r"], properties: { p: { type: "string" }, r: { type: "string" } } } },
      extra: { type: "object", description: "Datos propios del sector", properties: ex } } },
    siguiente: { type: "string", description: "La siguiente pregunta, una sola y corta. Vacío si terminas." },
    tema: { type: "string", description: "El tema de la siguiente pregunta, en 1 a 3 palabras" },
    terminado: { type: "boolean", description: "true si ya tienes lo necesario o llevas unas " + INT_ROUND + " preguntas en esta tanda" },
    cierre: { type: "string", description: "Si terminas: una frase de cierre, de tú" } } } };
}
function intPrompt(t, train, d, last) {
  const name = (train.negocio && train.negocio.nombre) || t.name, round = d.r || 0;
  return [
    "Eres la persona de 404 Content que entrevista al dueño de " + name + " para conocer su negocio a fondo y preparar sus vídeos cortos para redes (Instagram y TikTok) que grabará él mismo con el móvil.",
    "Haz UNA pregunta cada vez: corta, concreta, fácil de contestar hablando, de tú y en español de España, como en un chat. Nunca dos preguntas en una. Sin rodeos ni halagos. Si ayuda, da un ejemplo breve entre paréntesis.",
    "Lo que necesitamos, por orden, saltándote lo que ya esté claro abajo: 1) lo que vende y lo que más vende, con precios si quiere darlos; 2) su cliente típico y qué problema le resuelve; 3) por qué le eligen a él y no a otro; 4) las dudas y pegas que más oye y qué contesta; 5) el equipo y quién saldría en los vídeos; 6) la historia del negocio; 7) lo que se puede enseñar del día a día (procesos, preparación, detrás de cámaras); 8) casos o anécdotas reales que se puedan contar (sin datos personales); 9) promociones, temporadas y fechas fuertes; 10) lo que no quiere en sus vídeos; 11) cómo habla a sus clientes.",
    "Si una respuesta es vaga, repregunta una vez por lo mismo pidiendo un ejemplo concreto. Si no quiere contestar algo, pasa a otro tema.",
    "Guarda en `hechos` y en `actualizar` solo lo que diga él; no inventes ni completes con suposiciones." + ((NICHE[t.niche] || NICHE.general).med ? " Es un negocio sanitario: no le pidas casos con datos de pacientes." : ""),
    "Llevas " + round + " preguntas en esta tanda. Termina (`terminado`: true) cuando tengas lo importante o al llegar a unas " + INT_ROUND + ".",
    "",
    "=== Lo que ya sabemos del negocio ===",
    trainText(t.niche, train, "content"),
    d.qa.length ? "\n=== Lo último que le has preguntado ===\n" + d.qa.slice(-8).map((x) => "P: " + x.q + "\nR: " + (x.a || "(no ha querido contestar)")).join("\n") : "",
    "",
    last ? "Su respuesta a «" + last.q + "»: " + (last.a ? "«" + last.a + "»" : "(prefiere no contestar esta)") + "\nGuarda lo que cuente y haz la siguiente pregunta."
      : d.qa.length ? "Retomáis la entrevista otro rato: sin volver a saludar ni presentarte, haz la siguiente pregunta de lo que aún falte (puedes empezar con «Seguimos:»). Todo en `siguiente`."
      : "Empieza: una frase de saludo que diga que son unas preguntas rápidas para conocer su negocio y que puede contestar escribiendo o con notas de voz, y la primera pregunta. Todo en `siguiente`.",
  ].filter((l) => l !== "").join("\n");
}
// what an answer adds to the profile: empty fields are filled, lists grow, texts already written only grow with what is new
function mergeInterview(train, up, niche) {
  const filled = [];
  if (!up || typeof up !== "object") return filled;
  for (const k of ["negocio", "extra", "contenido"]) if (!train[k] || typeof train[k] !== "object") train[k] = {};
  const fill = (k, v, label, max, grow) => {
    v = str(v, max); if (!v) return;
    const cur = String(getPath(train, k) || "");
    if (!cur) { setPath(train, k, v); filled.push(label); return; }
    if (grow && !cur.toLowerCase().includes(v.toLowerCase().slice(0, 60)) && cur.length + v.length < max) { setPath(train, k, cur + "\n" + v); filled.push(label); }
  };
  fill("negocio.tipo", up.tipo, "tipo de negocio", 60);
  fill("negocio.ciudad", up.ciudad, "ciudad", 200);
  fill("negocio.sobre", up.sobre, "quiénes sois", 1500, true);
  fill("contenido.publico", up.publico, "a quién quieres llegar", 1500, true);
  fill("contenido.evitar", up.evitar, "lo que no quieres en tus vídeos", 1500, true);
  fill("contenido.redes", up.redes, "dónde publicas", 200);
  if (TONOS[up.tono] && train.contenido.tono !== up.tono) { train.contenido.tono = up.tono; filled.push("tono"); }
  const n = NICHE[niche] || NICHE.general, ex = up.extra && typeof up.extra === "object" ? up.extra : {};
  for (const x of n.extra) fill("extra." + x.k, ex[x.k], x.l.toLowerCase(), 1500, true);
  train.servicios = Array.isArray(train.servicios) ? train.servicios : [];
  let ns = 0;
  for (const s of (Array.isArray(up.servicios) ? up.servicios : []).slice(0, 20)) {
    const nombre = str(s && s.nombre, 80); if (!nombre) continue;
    const have = train.servicios.find((x) => String(x.nombre || "").toLowerCase() === nombre.toLowerCase());
    if (have) { if (!have.precio && str(s.precio, 60)) { have.precio = str(s.precio, 60); ns++; } if (!have.nota && str(s.nota, 300)) { have.nota = str(s.nota, 300); ns++; } }
    else if (train.servicios.length < 40) { train.servicios.push({ nombre, precio: str(s.precio, 60), dur: 30, nota: str(s.nota, 300) }); ns++; }
  }
  if (ns) filled.push("servicios");
  train.faq = Array.isArray(train.faq) ? train.faq : [];
  let nq = 0;
  for (const q of (Array.isArray(up.preguntas) ? up.preguntas : []).slice(0, 10)) {
    const p = str(q && q.p, 200), r = str(q && q.r, 800); if (!p || !r) continue;
    if (train.faq.some((x) => String(x.p || "").toLowerCase() === p.toLowerCase()) || train.faq.length >= 40) continue;
    train.faq.push({ p, r }); nq++;
  }
  if (nq) filled.push("preguntas frecuentes");
  return filled;
}
function addFacts(train, list) {
  const have = Array.isArray(train.saber) ? train.saber : [], seen = new Set(have.map((x) => String(x.t || "").toLowerCase())), now = Date.now(), out = [];
  for (const h of (Array.isArray(list) ? list : []).slice(0, 12)) { const t = str(String(h || ""), 300); if (t.length < 4 || seen.has(t.toLowerCase())) continue; seen.add(t.toLowerCase()); have.push({ t, ts: now }); out.push(t); }
  train.saber = have.slice(-INT_FACTS);
  return out;
}
/* 27 oct 2026, after the first try in production («La IA no ha respondido»): the question no longer depends on one way of asking. In order:
   1) the content model with the forced tool; 2) the same model answering a plain JSON, as the calendar does (that works in production);
   3) the quick model with the forced tool, as the free demo does. What failed is kept in p_cfg.int_last_error (Chris sees it in the admin). */
function intJsonShape(niche) {
  const keys = (NICHE[niche] || NICHE.general).extra.map((x) => "\"" + x.k + "\":\"\"").join(",");
  return "Devuelve SOLO un JSON, sin texto alrededor, con esta forma (deja vacío lo que no sepas): {\"hechos\":[\"…\"],\"actualizar\":{\"tipo\":\"\",\"ciudad\":\"\",\"sobre\":\"\",\"publico\":\"\",\"evitar\":\"\",\"redes\":\"\",\"tono\":\"\",\"servicios\":[{\"nombre\":\"\",\"precio\":\"\",\"nota\":\"\"}],\"preguntas\":[{\"p\":\"\",\"r\":\"\"}],\"extra\":{" + keys + "}},\"siguiente\":\"la siguiente pregunta\",\"tema\":\"\",\"terminado\":false,\"cierre\":\"\"}. tono solo puede ser " + Object.keys(TONOS).join(", ") + " o vacío.";
}
async function intErr(env, errs) {
  console.log("entrevista", errs.join(" | "));
  try { await env.DB.prepare("INSERT INTO p_cfg (k, v) VALUES ('int_last_error', ?1) ON CONFLICT(k) DO UPDATE SET v = excluded.v").bind(new Date().toISOString() + " " + errs.join(" | ").slice(0, 600)).run(); } catch (e) { console.log("int_last_error", e && e.message); }
}
async function intAsk(env, t, train, d, last) {
  const prompt = intPrompt(t, train, d, last), tool = intTool(t.niche), errs = [];
  const content = (await cfg(env, "model_content")) || "claude-sonnet-5-5", quick = (await cfg(env, "model")) || MODEL;
  const tries = [{ model: content, tool: true }, { model: content, tool: false }, { model: quick, tool: true }];
  for (const x of tries) {
    const req = x.tool ? { model: x.model, max_tokens: 2000, tools: [tool], tool_choice: { type: "tool", name: "entrevista" }, messages: [{ role: "user", content: prompt }] }
      : { model: x.model, max_tokens: 2000, messages: [{ role: "user", content: prompt + "\n\n" + intJsonShape(t.niche) }] };
    const r = await claude(env, t.id, req);
    if (r.error === "ai_off") return { error: "ai_off" };
    if (r.error) { errs.push(x.model + (x.tool ? " con herramienta" : " en JSON") + ": " + r.error + (r.detail ? " " + String(r.detail).slice(0, 160) : "")); continue; }
    let o = null;
    if (x.tool) { const tu = (r.content || []).find((b) => b.type === "tool_use" && b.name === "entrevista"); o = tu && tu.input && typeof tu.input === "object" ? tu.input : null; }
    if (!o) o = jsonOut(r);
    if (o && (str(o.siguiente, 600) || o.terminado === true)) { if (errs.length) await intErr(env, errs); return o; }
    errs.push(x.model + (x.tool ? " con herramienta" : " en JSON") + ": sin pregunta (" + (r.stop_reason || "?") + ")");
  }
  await intErr(env, errs);
  return { error: "ai" };
}
const intOut = (d, train, extra) => Object.assign({ cur: d.cur || null, round: d.r || 0, max: INT_ROUND, fin: !!d.fin, end: d.end || "",
  qa: d.qa.slice(-30).map((x) => ({ q: x.q, a: x.a, v: !!x.v, f: x.f || [], ts: x.ts })),
  facts: (Array.isArray(train.saber) ? train.saber : []).map((x, i) => ({ i, t: x.t })) }, extra || {});
async function apiInterview(req, env, me, p, M) {
  const t = await tenantOf(env, me.tenant_id), d = await intGet(env, t.id);
  let train = await getTrain(env, t.id);
  if (M === "GET") return json(intOut(d, train));
  const b = (await body(req, 6000000)) || {};
  if (p === "interview/stop") { d.cur = null; await intPut(env, t.id, d); return json(intOut(d, train)); }
  if (p === "interview/forget") {   // a fact the owner does not want the AI to use
    const i = Number(b.i), list = Array.isArray(train.saber) ? train.saber : [];
    if (!Number.isInteger(i) || i < 0 || i >= list.length) return bad("fact", 404);
    list.splice(i, 1); train.saber = list; await putTrain(env, t.id, train);
    return json(intOut(d, train));
  }
  if (p === "interview/next") {   // the first question, or the next round
    if (d.cur && d.cur.q) return json(intOut(d, train));
    if (!(await bump(env, t.id, "int", 80))) return bad("limit", 429);
    if (d.fin) { d.r = 0; d.fin = false; d.end = ""; }
    const o = await intAsk(env, t, train, d, null);
    if (o.error) return bad(o.error === "ai_off" ? "ai_off" : "ai", 502);
    const q = str(o.siguiente, 600); if (!q) return bad("ai", 502);
    d.cur = { q, tema: str(o.tema, 40) }; await intPut(env, t.id, d);
    return json(intOut(d, train));
  }
  if (p === "interview/answer") {
    if (!d.cur || !d.cur.q) return bad("nocur", 409);
    let a = str(b.a, 4000), heard = null, v = false;
    const audio = typeof b.audio === "string" && b.audio.length > 1000 && b.audio.length <= 5200000 && /^[A-Za-z0-9+/]+=*$/.test(b.audio) ? b.audio : "";
    if (audio) {
      if (!env.AI) return bad("noaudio", 503);
      try { const w = await env.AI.run("@cf/openai/whisper-large-v3-turbo", { audio, language: "es" }); heard = str((w && w.text) || "", 4000); }
      catch (e) { console.log("whisper", e && e.message); return bad("noaudio", 502); }
      if (!heard) return bad("unheard", 422);
      a = (a ? a + "\n" : "") + heard; v = true;
    }
    const skip = b.skip === true;
    if (!a && !skip) return bad("empty");
    if (!(await bump(env, t.id, "int", 80))) return bad("limit", 429);
    const last = { q: d.cur.q, a: skip ? "" : a };
    const o = await intAsk(env, t, train, d, last);
    if (o.error) return bad(o.error === "ai_off" ? "ai_off" : "ai", 502);
    train = await getTrain(env, t.id);   // fresh, in case the form was saved meanwhile
    let filled = [], facts = [];
    if (!skip) { filled = mergeInterview(train, o.actualizar, t.niche); facts = addFacts(train, o.hechos); await putTrain(env, t.id, train); }
    d.qa.push({ q: last.q, a: last.a, v, f: filled, ts: Date.now() }); d.qa = d.qa.slice(-200);
    d.r = (d.r || 0) + 1; d.n = (d.n || 0) + (skip ? 0 : 1);
    const next = str(o.siguiente, 600);
    if (o.terminado === true || !next || d.r >= INT_ROUND + 3) { d.cur = null; d.fin = true; d.end = str(o.cierre, 300) || "Con esto ya tengo mucho más de tu negocio. Tus próximas ideas lo van a notar."; }
    else d.cur = { q: next, tema: str(o.tema, 40) };
    await intPut(env, t.id, d);
    return json(intOut(d, train, { heard, filled, learned: facts, progress: trainProgress(t.niche, train, planOf(t)) }));
  }
  return bad("nope", 404);
}
